def curve(k,name,d,description,width=.43,opacity=.65):
    s['parts'][k]['geometry'].append(dict(name=name,d=d,role='structure',final='visible',desc=f'{GROUP}/{k}；'+description,width=width,color='#8190A8',opacity=opacity))
