prepare('part_structure',s,'# 3.2 内部结构线\n\n依据两件完整发面建立疏而连续的纵向发流。宽幕围绕耳后、颈背、腰髋和下返面逐渐展开；侧长束保留从耳后根到自由卷尖的S形体积。隐藏同面延续结构，闭合边不当成发沟。所有曲线具有唯一ID与起止、压力、软硬、淡出和最终显影描述。',line=True)
